from taf.fdsw.rc.interface import rc

from taf.rfrl.procedures.resources.python.testline.TestLine import TestLine
from taf.rfrl.procedures.resources.python.connections import get_http_connection_credentials
from taf.rfrl.procedures.resources.python.logger import log_input_and_output, log_operation


class RescueConsole:

    def __init__(self):
        self._rc_connection = rc()
        self._remote_connection = None
        self._alias = None

    def connect(self, bts_type):
        """
        Creates connection to FDSW Rescue Console for provided BTS type.

        :param bts_type: type of bts to which connection should be made ('GNB' or 'ENB')
        :type bts_type: str
        """

        self._alias = f"SISO_RC_CONNECTION_{bts_type}"
        credentials = self._get_connection_credentials(bts_type=bts_type)

        if TestLine().get_bts_setup_mode() == "NSA" and bts_type == "ENB":
            self._setup_remote_connection(bts_type=bts_type)

        self._rc_connection.connect_to(
            ip_address=credentials['ip'], port=credentials['port'], username=credentials['username'],
            password=credentials['password'], name=self._alias, auto_discover=True, secure=True
        )

    def enable_ssh_service(self, timeout=30):
        """
        Enables SSH service on BTS.

        :param timeout: Keyword execution timeout.
        :type timeout: Union[int,str]
        """

        log_operation("Enabling SSH service ...")
        self._rc_connection.enable_ssh_service(timeout=timeout, connection=self._alias)

    def rollback_to_active_sw_partition(self):
        """
        Activates SW on partition that is set as active.
        """

        self._software_rollback(sw_slot_id=self._get_active_sw_partition())

    def teardown_connections(self):
        """
        Closes all connections to FDSW Rescue Console.
        """

        if self._remote_connection:
            self._rc_connection.disconnect_remote(self._remote_connection)

        self._rc_connection.teardown(connection=self._alias)

    @log_input_and_output
    def _software_rollback(self, sw_slot_id, timeout=10):
        log_operation(f"Executing SW rollback to version: "
                      f"{self._rc_connection.get_sw_version_name(sw_slot_id=sw_slot_id, connection=self._alias)}")
        self._rc_connection.software_rollback(sw_slot_id=sw_slot_id, timeout=timeout, connection=self._alias)

    @log_input_and_output
    def _get_active_sw_partition(self, timeout=10):
        return self._rc_connection.get_active_sw_partition(timeout=timeout, connection=self._alias)

    @staticmethod
    @log_input_and_output
    def _get_connection_credentials(bts_type):
        credentials = get_http_connection_credentials(bts_type=bts_type)

        if TestLine().get_bts_setup_mode() == "NSA" and bts_type == "ENB":
            credentials['ip'] = "localhost"
            credentials['port'] = 8888

        return credentials

    def _setup_remote_connection(self, bts_type):
        testpc_credentials = TestLine().get_bts_test_pc_credentials(bts_type=bts_type)
        connection_credentials = self._get_connection_credentials(bts_type=bts_type)

        self._remote_connection = self._rc_connection.setup_remote(ssh_host=testpc_credentials['host'],
                                                                   ssh_username=testpc_credentials['user'],
                                                                   ssh_password=testpc_credentials['password'],
                                                                   ssh_port=22,
                                                                   local_host=connection_credentials['ip'],
                                                                   local_port=connection_credentials['port'])
